//[SysClientCacheDataMethodAttribute(true)]
public static str PlacedBy(SalesTable _this)
{   
    changecompany(curExt())
    {
        HcmWorker worker;
        worker = HcmWorker::find(_this.WorkerSalesTaker);

        DirPerson   dirPerson;

        select firstonly NameAlias from dirPerson where dirPerson.RecId == worker.Person;       

        if (!dirPerson.NameAlias)
        {
            return 'Website';
        }
        else
        {
            return dirPerson.NameAlias;
        }
    }

}

[SysClientCacheDataMethodAttribute(true)]
public static real SalesOrderTotal(SalesTable _this)
{
    changecompany(curExt())
    {
        SalesTotals salesTotals;
        salesTotals = SalesTotals::construct(_this, SalesUpdate::All);
        salesTotals.calc();

        AmountCur totalAmount;
        totalAmount = salesTotals.totalAmount();        

        return totalAmount;
    }
}

//[SysClientCacheDataMethodAttribute(true)]
public static real ItemQuantityTotals(SalesTable _this)
{   
    SalesLine salesLine;
    changecompany(curExt())
    {
        real total = (select sum(SalesQty) from salesLine
        where salesLine.SalesId == _this.SalesId).SalesQty;

        return total;
    }
}

//[SysClientCacheDataMethodAttribute(true)]
public static Description ShippingAddress(SalesTable _this)
{   
    changecompany(curExt())
    {
        return _this.deliveryAddress().Address; //SalesTable.deliveryAddress().Address;
    }
}

//[SysClientCacheDataMethodAttribute(true)]
public static real ShippingCost(SalesTable _this)
{
    changecompany(curExt())
    {
        MarkupAutoTable markupAutoTable;
        MarkupAutoLine  markupAutoLine;
        DlvMode         dlvMode;

        select dlvMode
            where _this.DlvMode == dlvMode.Code;

        select firstonly markupAutoLine
            where markupAutoLine.MarkupCode == dlvMode.MarkupGroup;

        return markupAutoLine.Value;
    }
}

//[SysClientCacheDataMethodAttribute(true)]
public static Description DlvMode(SalesTable _this)
{         
    changecompany(curExt())
    {
        DlvMode         dlvMode;            

        select dlvMode
            where _this.DlvMode == dlvMode.Code;        

        return dlvMode.Txt;
    }
}

[SysClientCacheDataMethodAttribute(true)]
public static AttributeValueText PaytraceId(SalesTable _this)
{
    RetailTransactionAttributeTrans retailTransAttrTrans;
    RetailTransactionTable          retailTransTable;
    changecompany(curExt())
    {
        SalesTable salesTable = SalesTable::find(_this.SalesId);


        select retailTransAttrTrans
        join retailTransTable
        where retailTransTable.transactionId == retailTransAttrTrans.transactionId &&
                retailTransAttrTrans.Name == 'Paytrace id' &&
                retailTransTable.salesOrderId == salesTable.SalesId;

        AttributeValueText transactionId = retailTransAttrTrans.TextValue;

        return transactionId;
    }
}

